      loadingType: 'more',
      //加载更多状态
      goodsList: [],
      oddgoodsList: [],
      evengoodsList: [],
      goods_id: "",
      orderBy: "add_date asc",
      currentPage: 1,
      // 当前页码
      pageSize: 8,
      // 每页数据条数
      goodsArr: [],
